#!/usr/bin/env bun
/**
 * Discord channel for Claude Code.
 *
 * Self-contained MCP server with full access control: pairing, allowlists,
 * guild-channel support with mention-triggering. State lives in
 * <config>/channels/discord/access.json — managed by the /discord:access skill.
 *
 * Discord's search API isn't exposed to bots — fetch_messages is the only
 * lookback, and the instructions tell the model this.
 */

import { Server } from '@modelcontextprotocol/sdk/server/index.js'
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js'
import {
  ListToolsRequestSchema,
  CallToolRequestSchema,
} from '@modelcontextprotocol/sdk/types.js'
import { z } from 'zod'
import {
  Client,
  GatewayIntentBits,
  Partials,
  ChannelType,
  ButtonBuilder,
  ButtonStyle,
  ActionRowBuilder,
  type Message,
  type Attachment,
  type Interaction,
} from 'discord.js'
import { randomBytes } from 'crypto'
import { readFileSync, writeFileSync, mkdirSync, readdirSync, rmSync, statSync, renameSync, realpathSync, chmodSync } from 'fs'
import { homedir } from 'os'
import { join, sep } from 'path'

const STATE_DIR = join(process.env.CLAUDE_CONFIG_DIR ?? join(homedir(), '.claude'), 'channels', 'discord')
const ACCESS_FILE = join(STATE_DIR, 'access.json')
const APPROVED_DIR = join(STATE_DIR, 'approved')
const ENV_FILE = join(STATE_DIR, '.env')

// Load STATE_DIR/.env into process.env. Real env wins.
// Plugin-spawned servers don't get an env block — this is where the token lives.
try {
  // Token is a credential — lock to owner. No-op on Windows (would need ACLs).
  chmodSync(ENV_FILE, 0o600)
  for (const line of readFileSync(ENV_FILE, 'utf8').split('\n')) {
    const m = line.match(/^(\w+)=(.*)$/)
    if (m && process.env[m[1]] === undefined) process.env[m[1]] = m[2]
  }
} catch {}

const TOKEN = process.env.DISCORD_BOT_TOKEN
const STATIC = process.env.DISCORD_ACCESS_MODE === 'static'

if (!TOKEN) {
  process.stderr.write(
    `discord channel: DISCORD_BOT_TOKEN required\n` +
    `  set in ${ENV_FILE}\n` +
    `  format: DISCORD_BOT_TOKEN=MTIz...\n`,
  )
  process.exit(1)
}
const INBOX_DIR = join(STATE_DIR, 'inbox')

// Last-resort safety net — without these the process dies silently on any
// unhandled promise rejection. With them it logs and keeps serving tools.
process.on('unhandledRejection', err => {
  process.stderr.write(`discord channel: unhandled rejection: ${err}\n`)
})
process.on('uncaughtException', err => {
  process.stderr.write(`discord channel: uncaught exception: ${err}\n`)
})

// Permission-reply spec from anthropics/claude-cli-internal
// src/services/mcp/channelPermissions.ts — inlined (no CC repo dep).
// 5 lowercase letters a-z minus 'l'. Case-insensitive for phone autocorrect.
// Strict: no bare yes/no (conversational), no prefix/suffix chatter.
const PERMISSION_REPLY_RE = /^\s*(y|yes|n|no)\s+([a-km-z]{5})\s*$/i

const client = new Client({
  intents: [
    GatewayIntentBits.DirectMessages,
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
  // DMs arrive as partial channels — messageCreate never fires without this.
  partials: [Partials.Channel],
})

type PendingEntry = {
  senderId: string
  chatId: string // DM channel ID — where to send the approval confirm
  createdAt: number
  expiresAt: number
  replies: number
}

type GroupPolicy = {
  requireMention: boolean
  allowFrom: string[]
  allowBots?: boolean
}

type Access = {
  dmPolicy: 'pairing' | 'allowlist' | 'disabled'
  allowFrom: string[]
  /** Keyed on channel ID (snowflake), not guild ID. One entry per guild channel. */
  groups: Record<string, GroupPolicy>
  pending: Record<string, PendingEntry>
  mentionPatterns?: string[]
  // delivery/UX config — optional, defaults live in the reply handler
  /** Emoji to react with on receipt. Empty string disables. Unicode char or custom emoji ID. */
  ackReaction?: string
  /** Which chunks get Discord's reply reference when reply_to is passed. Default: 'first'. 'off' = never thread. */
  replyToMode?: 'off' | 'first' | 'all'
  /** Max chars per outbound message before splitting. Default: 2000 (Discord's hard cap). */
  textChunkLimit?: number
  /** Split on paragraph boundaries instead of hard char count. */

content.content:
120	  /** Split on paragraph boundaries instead of hard char count. */
121	  chunkMode?: 'length' | 'newline'
122	  /** Allow messages from other bots. Default: false. Self-messages are always ignored. */
123	  allowBots?: boolean
124	}
125	
126	function defaultAccess(): Access {
127	  return {
128	    dmPolicy: 'pairing',
129	    allowFrom: [],
130	    groups: {},
131	    pending: {},
132	  }
133	}
134	
135	const MAX_CHUNK_LIMIT = 2000
136	const MAX_ATTACHMENT_BYTES = 25 * 1024 * 1024
137	
138	// reply's files param takes any path. .env is ~60 bytes and ships as an
139	// upload. Claude can already Read+paste file contents, so this isn't a new
140	// exfil channel for arbitrary paths — but the server's own state is the one
141	// thing Claude has no reason to ever send.
142	function assertSendable(f: string): void {
143	  let real, stateReal: string
144	  try {
145	    real = realpathSync(f)
146	    stateReal = realpathSync(STATE_DIR)
147	  } catch { return } // statSync will fail properly; or STATE_DIR absent → nothing to leak
148	  const inbox = join(stateReal, 'inbox')
149	  if (real.startsWith(stateReal + sep) && !real.startsWith(inbox + sep)) {
150	    throw new Error(`refusing to send channel state: ${f}`)
151	  }
152	}
153	
154	function readAccessFile(): Access {
155	  try {
156	    const raw = readFileSync(ACCESS_FILE, 'utf8')
