    for (const userId of access.allowFrom) {
      void (async () => {
        try {
          const user = await client.users.fetch(userId)
          await user.send({ content: text, components: [row] })
        } catch (e) {
          process.stderr.write(`permission_request send to ${userId} failed: ${e}\n`)
        }
      })()
    }
  },
)

