mcp.setRequestHandler(CallToolRequestSchema, async req => {
  const args = (req.params.arguments ?? {}) as Record<string, unknown>
  try {
    switch (req.params.name) {
      case 'reply': {
        const chat_id = args.chat_id as string
        const text = args.text as string
        const reply_to = args.reply_to as string | undefined
        const files = (args.files as string[] | undefined) ?? []

        const ch = await fetchAllowedChannel(chat_id)
        if (!('send' in ch)) throw new Error('channel is not sendable')

        for (const f of files) {
          assertSendable(f)
          const st = statSync(f)
          if (st.size > MAX_ATTACHMENT_BYTES) {
            throw new Error(`file too large: ${f} (${(st.size / 1024 / 1024).toFixed(1)}MB, max 25MB)`)
          }
        }
        if (files.length > 10) throw new Error('Discord allows max 10 attachments per message')

        const access = loadAccess()
        const limit = Math.max(1, Math.min(access.textChunkLimit ?? MAX_CHUNK_LIMIT, MAX_CHUNK_LIMIT))
        const mode = access.chunkMode ?? 'length'
        const replyMode = access.replyToMode ?? 'first'
        const chunks = chunk(text, limit, mode)
        const sentIds: string[] = []

        try {
          for (let i = 0; i < chunks.length; i++) {
            const shouldReplyTo =
              reply_to != null &&
              replyMode !== 'off' &&
              (replyMode === 'all' || i === 0)
            const sent = await ch.send({
              content: chunks[i],
              ...(i === 0 && files.length > 0 ? { files } : {}),
              ...(shouldReplyTo
                ? { reply: { messageReference: reply_to, failIfNotExists: false } }
                : {}),
            })
            noteSent(sent.id)
            sentIds.push(sent.id)
          }
        } catch (err) {
          const msg = err instanceof Error ? err.message : String(err)
          throw new Error(`reply failed after ${sentIds.length} of ${chunks.length} chunk(s) sent: ${msg}`)
        }

        const result =
          sentIds.length === 1
            ? `sent (id: ${sentIds[0]})`
            : `sent ${sentIds.length} parts (ids: ${sentIds.join(', ')})`
        return { content: [{ type: 'text', text: result }] }
      }
      case 'fetch_messages': {
        const ch = await fetchAllowedChannel(args.channel as string)
        const limit = Math.min((args.limit as number) ?? 20, 100)
        const msgs = await ch.messages.fetch({ limit })
        const me = client.user?.id
        const arr = [...msgs.values()].reverse()
        const out =
          arr.length === 0
            ? '(no messages)'
            : arr
                .map(m => {
                  const who = m.author.id === me ? 'me' : m.author.username
                  const atts = m.attachments.size > 0 ? ` +${m.attachments.size}att` : ''
                  // Tool result is newline-joined; multi-line content forges
                  // adjacent rows. History includes ungated senders (no-@mention
                  // messages in an opted-in channel never hit the gate but
                  // still live in channel history).
                  const text = m.content.replace(/[\r\n]+/g, ' ⏎ ')
                  return `[${m.createdAt.toISOString()}] ${who}: ${text}  (id: ${m.id}${atts})`
                })
                .join('\n')
        return { content: [{ type: 'text', text: out }] }
      }
      case 'react': {
        const ch = await fetchAllowedChannel(args.chat_id as string)
        const msg = await ch.messages.fetch(args.message_id as string)
        await msg.react(args.emoji as string)
        return { content: [{ type: 'text', text: 'reacted' }] }
      }
      case 'edit_message': {
        const ch = await fetchAllowedChannel(args.chat_id as string)
        const msg = await ch.messages.fetch(args.message_id as string)
        const edited = await msg.edit(args.text as string)
        return { content: [{ type: 'text', text: `edited (id: ${edited.id})` }] }
      }
      case 'download_attachment': {
        const ch = await fetchAllowedChannel(args.chat_id as string)
        const msg = await ch.messages.fetch(args.message_id as string)
        if (msg.attachments.size === 0) {
          return { content: [{ type: 'text', text: 'message has no attachments' }] }
        }
        const lines: string[] = []
        for (const att of msg.attachments.values()) {
          const path = await downloadAttachment(att)
          const kb = (att.size / 1024).toFixed(0)
          lines.push(`  ${path}  (${safeAttName(att)}, ${att.contentType ?? 'unknown'}, ${kb}KB)`)
        }
        return {
          content: [{ type: 'text', text: `downloaded ${lines.length} attachment(s):\n${lines.join('\n')}` }],
        }
      }
      default:
        return {
          content: [{ type: 'text', text: `unknown tool: ${req.params.name}` }],
          isError: true,
        }
    }
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err)
    return {
      content: [{ type: 'text', text: `${req.params.name} failed: ${msg}` }],
      isError: true,
    }
  }
})

await mcp.connect(new StdioServerTransport())

// When Claude Code closes the MCP connection, stdin gets EOF. Without this
// the gateway stays connected as a zombie holding resources.
let shuttingDown = false
function shutdown(): void {
  if (shuttingDown) return
  shuttingDown = true
  process.stderr.write('discord channel: shutting down\n')
  setTimeout(() => process.exit(0), 2000)
  void Promise.resolve(client.destroy()).finally(() => process.exit(0))
}
process.stdin.on('end', shutdown)
process.stdin.on('close', shutdown)
process.on('SIGTERM', shutdown)
process.on('SIGINT', shutdown)

client.on('error', err => {
  process.stderr.write(`discord channel: client error: ${err}\n`)
})

// Button-click handler for permission requests. customId is
// `perm:allow:<id>`, `perm:deny:<id>`, or `perm:more:<id>`.
// Security mirrors the text-reply path: allowFrom must contain the sender.
client.on('interactionCreate', async (interaction: Interaction) => {
  if (!interaction.isButton()) return
  const m = /^perm:(allow|deny|more):([a-km-z]{5})$/.exec(interaction.customId)
  if (!m) return
  const access = loadAccess()
  if (!access.allowFrom.includes(interaction.user.id)) {
    await interaction.reply({ content: 'Not authorized.', ephemeral: true }).catch(() => {})
    return
  }
  const [, behavior, request_id] = m

  if (behavior === 'more') {
    const details = pendingPermissions.get(request_id)
    if (!details) {
      await interaction.reply({ content: 'Details no longer available.', ephemeral: true }).catch(() => {})
      return
    }
    const { tool_name, description, input_preview } = details
    let prettyInput: string
    try {
      prettyInput = JSON.stringify(JSON.parse(input_preview), null, 2)
    } catch {
      prettyInput = input_preview
    }
    const expanded =
      `🔐 Permission: ${tool_name}\n\n` +
      `tool_name: ${tool_name}\n` +
      `description: ${description}\n` +
      `input_preview:\n${prettyInput}`
    const row = new ActionRowBuilder<ButtonBuilder>().addComponents(
      new ButtonBuilder()
        .setCustomId(`perm:allow:${request_id}`)
        .setLabel('Allow')
        .setEmoji('✅')
        .setStyle(ButtonStyle.Success),
      new ButtonBuilder()
        .setCustomId(`perm:deny:${request_id}`)
        .setLabel('Deny')
        .setEmoji('❌')
        .setStyle(ButtonStyle.Danger),
    )
    await interaction.update({ content: expanded, components: [row] }).catch(() => {})
    return
  }

  void mcp.notification({
    method: 'notifications/claude/channel/permission',
    params: { request_id, behavior },
  })
  pendingPermissions.delete(request_id)
  const label = behavior === 'allow' ? '✅ Allowed' : '❌ Denied'
  // Replace buttons with the outcome so the same request can't be answered
  // twice and the chat history shows what was chosen.
  await interaction
    .update({ content: `${interaction.message.content}\n\n${label}`, components: [] })
    .catch(() => {})
})

client.on('messageCreate', msg => {
  // Always ignore own messages to prevent infinite loops.
  if (msg.author.id === client.user?.id) return
  // Block bot messages unless allowBots is enabled (globally or per-group).
  if (msg.author.bot) {
    const access = loadAccess()
    const isDM = msg.channel.type === ChannelType.DM
    if (isDM) {
      if (!access.allowBots) {
        process.stderr.write(`discord: bot msg dropped (DM, allowBots=false) from ${msg.author.username}\n`)
        return
      }
    } else {
      const channelId = msg.channel.isThread?.()
        ? (msg.channel as any).parentId ?? msg.channelId
        : msg.channelId
      const groupPolicy = access.groups[channelId]
      if (!groupPolicy?.allowBots && !access.allowBots) {
        process.stderr.write(`discord: bot msg dropped (group ch=${channelId}, groupAllowBots=${groupPolicy?.allowBots}, globalAllowBots=${access.allowBots}) from ${msg.author.username}\n`)
        return
      }
      process.stderr.write(`discord: bot msg PASSED filter (group ch=${channelId}) from ${msg.author.username}\n`)
    }
  }
  handleInbound(msg).catch(e => process.stderr.write(`discord: handleInbound failed: ${e}\n`))
})

async function handleInbound(msg: Message): Promise<void> {
  const result = await gate(msg)

  if (result.action === 'drop') return

  if (result.action === 'pair') {
    const lead = result.isResend ? 'Still pending' : 'Pairing required'
    try {
      await msg.reply(
        `${lead} — run in Claude Code:\n\n/discord:access pair ${result.code}`,
      )
    } catch (err) {
      process.stderr.write(`discord channel: failed to send pairing code: ${err}\n`)
    }
    return
  }

  const chat_id = msg.channelId

  // Permission-reply intercept: if this looks like "yes xxxxx" for a
  // pending permission request, emit the structured event instead of
  // relaying as chat. The sender is already gate()-approved at this point
  // (non-allowlisted senders were dropped above), so we trust the reply.
  const permMatch = PERMISSION_REPLY_RE.exec(msg.content)
  if (permMatch) {
    void mcp.notification({
      method: 'notifications/claude/channel/permission',
      params: {
        request_id: permMatch[2]!.toLowerCase(),
        behavior: permMatch[1]!.toLowerCase().startsWith('y') ? 'allow' : 'deny',
      },
    })
    const emoji = permMatch[1]!.toLowerCase().startsWith('y') ? '✅' : '❌'
    void msg.react(emoji).catch(() => {})
    return
  }

  // Typing indicator — signals "processing" until we reply (or ~10s elapses).
  if ('sendTyping' in msg.channel) {
    void msg.channel.sendTyping().catch(() => {})
  }

  // Ack reaction — lets the user know we're processing. Fire-and-forget.
  const access = result.access
  if (access.ackReaction) {
    void msg.react(access.ackReaction).catch(() => {})
  }

  // Attachments are listed (name/type/size) but not downloaded — the model
  // calls download_attachment when it wants them. Keeps the notification
  // fast and avoids filling inbox/ with images nobody looked at.
  const atts: string[] = []
  for (const att of msg.attachments.values()) {
    const kb = (att.size / 1024).toFixed(0)
    atts.push(`${safeAttName(att)} (${att.contentType ?? 'unknown'}, ${kb}KB)`)
  }

  // Attachment listing goes in meta only — an in-content annotation is
  // forgeable by any allowlisted sender typing that string.
  const content = msg.content || (atts.length > 0 ? '(attachment)' : '')

  mcp.notification({
    method: 'notifications/claude/channel',
    params: {
      content,
      meta: {
        chat_id,
        message_id: msg.id,
        user: msg.author.username,
        user_id: msg.author.id,
        ts: msg.createdAt.toISOString(),
        ...(atts.length > 0 ? { attachment_count: String(atts.length), attachments: atts.join('; ') } : {}),
      },
    },
  }).catch(err => {
    process.stderr.write(`discord channel: failed to deliver inbound to Claude: ${err}\n`)
  })
}

client.once('ready', c => {
  process.stderr.write(`discord channel: gateway connected as ${c.user.tag}\n`)
})

client.login(TOKEN).catch(err => {
  process.stderr.write(`discord channel: login failed: ${err}\n`)
  process.exit(1)
})

